//! Checks `subsearch legacy ...` against output recorded from the original C programs
//! (`tests/fixtures`, regenerated by `scripts/make_fixtures.sh`): stdout, stderr and exit status
//! must match byte for byte, except for the CPU time and host name `sub_search` prints last.

use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};

fn fixtures(program: &str) -> Vec<PathBuf> {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/fixtures")
        .join(program);
    let mut inputs: Vec<PathBuf> = std::fs::read_dir(&dir)
        .unwrap()
        .map(|e| e.unwrap().path())
        .filter(|p| p.extension().is_some_and(|e| e == "in"))
        .collect();
    inputs.sort();
    assert!(!inputs.is_empty(), "no fixtures in {}", dir.display());
    inputs
}

fn strip_timing(s: &str) -> String {
    match s.find("T> ") {
        Some(i) => s[..i].to_string() + "T>",
        None => s.to_string(),
    }
}

fn check(program: &str, subcommand: &str) {
    let mut failures = Vec::new();
    for input in fixtures(program) {
        let expected = |ext: &str| std::fs::read_to_string(input.with_extension(ext)).unwrap();
        let output = Command::new(env!("CARGO_BIN_EXE_subsearch"))
            .args(["legacy", subcommand])
            .stdin(Stdio::from(std::fs::File::open(&input).unwrap()))
            .output()
            .unwrap();
        let stdout = String::from_utf8(output.stdout).unwrap();
        let stderr = String::from_utf8(output.stderr).unwrap();
        let status = output.status.code().unwrap().to_string();
        let name = input.file_stem().unwrap().to_string_lossy().to_string();
        if strip_timing(&stdout) != strip_timing(&expected("out")) {
            failures.push(format!("{name}: stdout differs"));
        }
        if stderr != expected("err") {
            failures.push(format!(
                "{name}: stderr {stderr:?} != {:?}",
                expected("err")
            ));
        }
        if status != expected("status").trim() {
            failures.push(format!(
                "{name}: exit status {status} != {}",
                expected("status").trim()
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn ggen_matches_the_c_program() {
    check("ggen", "ggen");
}

#[test]
fn sub_search_matches_the_c_program() {
    check("sub_search", "sub-search");
}
